<?php require_once __DIR__.'/../api/bootstrap.php';require_login();$m=current_medico();$err='';$aid=(int)($_GET['atendimento_id']??0);$s=db()->prepare('SELECT id,nome FROM pacientes WHERE medico_id=? ORDER BY nome');$s->execute([$m['id']]);$ps=$s->fetchAll();$pre=[];if($aid){$s=db()->prepare('SELECT * FROM atendimentos WHERE id=? AND medico_id=?');$s->execute([$aid,$m['id']]);$pre=$s->fetch()?:[];}if($_SERVER['REQUEST_METHOD']==='POST'){require_csrf();$pid=(int)$_POST['paciente_id'];$p=patient_for_doctor($pid,$m['id']);$v=[];foreach(['titulo','historico_clinico','avaliacao','exames','cid_codigo','cid_descricao','atividade_habitual','repercussao','periodo_estimado','incapacidade_restricao','conclusao','conteudo_personalizado'] as $f)$v[$f]=trim($_POST[$f]??'');if(!$p)$err='Paciente inválido.';elseif(!$v['conclusao'])$err='A conclusão é obrigatória.';elseif(empty($_POST['confirmar']))$err='Confirme a revisão médica.';else{$code=unique_code('LAUD');$q=db()->prepare('INSERT INTO laudos(paciente_id,medico_id,atendimento_id,codigo_validacao,data_emissao,titulo,conteudo_personalizado,historico_clinico,avaliacao,exames,cid_codigo,cid_descricao,atividade_habitual,repercussao,periodo_estimado,incapacidade_restricao,conclusao,status) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)');$q->execute([$pid,$m['id'],$aid?:null,$code,date('Y-m-d H:i:s'),$v['titulo']?:'Laudo Médico',$v['conteudo_personalizado'],$v['historico_clinico'],$v['avaliacao'],$v['exames'],$v['cid_codigo'],$v['cid_descricao'],$v['atividade_habitual'],$v['repercussao'],$v['periodo_estimado'],$v['incapacidade_restricao'],$v['conclusao'],'EMITIDO']);$id=db()->lastInsertId();audit_log('emitir_laudo','laudos',$id,['codigo'=>$code]);header('Location:view.php?id='.$id);exit;}}render_header('Novo laudo');?><h1>Laudo médico personalizado</h1><?php if($err):?><div class="error"><?=e($err)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="card"><div class="grid"><div><label>Paciente *</label><select name="paciente_id" required><option value="">Selecione</option><?php foreach($ps as $p):?><option value="<?=$p['id']?>"><?=e($p['nome'])?></option><?php endforeach;?></select></div><div><label>Título</label><input name="titulo" value="Laudo Médico"></div><div><label>Atividade habitual</label><input name="atividade_habitual"></div><div><label>Período estimado</label><input name="periodo_estimado"></div></div></div><?php foreach([['historico_clinico','História clínica'],['avaliacao','Avaliação / exame físico'],['exames','Exames complementares'],['repercussao','Repercussão funcional'],['incapacidade_restricao','Incapacidade/restrições'],['conclusao','Conclusão médica *']] as $f):?><div class="card"><label><?=e($f[1])?></label><textarea name="<?=$f[0]?>" <?=str_contains($f[0],'conclusao')?'required':''?>><?=e($pre[$f[0]]??'')?></textarea></div><?php endforeach;?><div class="card"><h2>CID-10</h2><div class="grid"><div><label>Código</label><input id="cc" name="cid_codigo"><div id="cr" class="cid-results"></div></div><div><label>Descrição</label><input id="cd" name="cid_descricao"></div></div></div><div class="card"><label>Texto personalizado</label><textarea name="conteudo_personalizado" rows="12"></textarea></div><div class="card"><label><input type="checkbox" name="confirmar" value="1" required> Revisei o conteúdo, diagnóstico/CID e conclusão. Autorizo a emissão e assinatura.</label></div><button class="btn ok">Assinar e emitir</button></form><script>const c=document.querySelector('#cc'),d=document.querySelector('#cd'),r=document.querySelector('#cr');let t;c.oninput=()=>{clearTimeout(t);if(c.value.length<2){r.innerHTML='';return}t=setTimeout(()=>fetch('/medical/cid/search.php?q='+encodeURIComponent(c.value)).then(x=>x.json()).then(a=>r.innerHTML=a.map(x=>'<button type="button" onclick="pick(\''+x.codigo+'\',\''+x.descricao.replaceAll("'","\\'")+'\')"><b>'+x.codigo+'</b> — '+x.descricao+'</button>').join('')),250)};function pick(a,b){c.value=a;d.value=b;r.innerHTML='';}</script><?php render_footer();?>